// Server-side reader for the opponent field.
//
// Split out of record.ts because the client imports that module to score a
// lineup live as it's built, and anything reachable from a client component
// must not import 'fs'. The scoring rules are pure and shared; reading the
// file they run against happens only here.
//
// The file is generated by scripts/build-minigame-benchmark.mjs and lives at
// public/data/minigames/benchmark.json.

import { promises as fs } from 'fs'
import path from 'path'
import type { ScoringProfile } from './ranks'
import { GAMES, type Benchmark } from './record'

type BenchmarkFile = {
  games: number
  profiles: Record<string, { thresholds: number[]; median: number; sampleSize: number }>
}

const FILE = path.join(process.cwd(), 'public', 'data', 'minigames', 'benchmark.json')

let cached: Promise<BenchmarkFile | null> | null = null

function readFile(): Promise<BenchmarkFile | null> {
  if (!cached) {
    const fresh = fs
      .readFile(FILE, 'utf-8')
      .then((raw) => JSON.parse(raw) as BenchmarkFile)
      .catch(() => null)
    cached = fresh
    // A missing or unreadable file shouldn't be remembered as "missing" for
    // the life of the instance — drop it so the next caller retries.
    void fresh.then((v) => {
      if (!v && cached === fresh) cached = null
    })
  }
  return cached
}

export async function loadBenchmark(profile: ScoringProfile): Promise<Benchmark | null> {
  const file = await readFile()
  const entry = file?.profiles?.[profile]
  if (!entry || !Array.isArray(entry.thresholds) || entry.thresholds.length !== GAMES) {
    return null
  }
  return { profile, thresholds: entry.thresholds, median: entry.median }
}
